"use strict";(()=>{const input=document.getElementById('newsSearch');const clear=document.getElementById('newsClear');const count=document.getElementById('newsCount');const empty=document.getElementById('newsEmpty');const featured=document.querySelector('.news-featured');const cards=[...document.querySelectorAll('.news-card')];const filters=[...document.querySelectorAll('.news-filter')];let topic='all';const normalise=(text)=>text.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d');cards.forEach((card)=>{card.dataset.index=normalise(card.dataset.search+' '+card.textContent);});function update(){const words=normalise(input.value.trim()).split(/\s+/).filter(Boolean);const browsing=topic==='all'&&!words.length;let shown=0;cards.forEach((card)=>{const match=(topic==='all'||card.dataset.topic===topic)&&words.every((word)=>card.dataset.index.includes(word));card.hidden=!match||(browsing&&card.hasAttribute('data-featured'));if(match)shown+=1;});featured.hidden=!browsing;clear.hidden=!input.value;empty.hidden=shown>0;count.textContent=shown===1?'1 story':`${shown} stories`;}
input.addEventListener('input',update);input.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&input.value){input.value='';update();}});clear.addEventListener('click',()=>{input.value='';update();input.focus();});filters.forEach((button)=>button.addEventListener('click',()=>{topic=button.dataset.filter;filters.forEach((item)=>item.setAttribute('aria-pressed',String(item===button)));update();}));document.getElementById('newsReset').addEventListener('click',()=>{input.value='';topic='all';filters.forEach((item)=>item.setAttribute('aria-pressed',String(item.dataset.filter==='all')));update();});const status=document.getElementById('newsStatus');let timer;document.querySelectorAll('[data-route]').forEach((button)=>button.addEventListener('click',()=>{if(parent!==window){parent.postMessage({namespace:'ctuav-demo',type:'route',route:button.dataset.route},'*');return;}
status.textContent='This link opens the story page in the combined demo';status.hidden=false;clearTimeout(timer);timer=setTimeout(()=>{status.hidden=true;},3600);}));update();})();addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='palette')return;const theme=event.data.theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelectorAll('.palette-button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===theme);button.setAttribute('aria-pressed',String(button.dataset.palette===theme));});});addEventListener('message',event=>{if(event.source===parent&&event.data?.namespace==='ctuav-demo'&&event.data.type==='view-active'&&event.data.active)scrollTo({top:0,behavior:'instant'});});"use strict";(()=>{document.querySelectorAll('[data-footer-route]').forEach((button)=>button.addEventListener('click',()=>{const route=button.dataset.footerRoute;if(window.ctuavDemo)window.ctuavDemo.navigate(route);else if(parent!==window)parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');}));})();